function meetingCost(rates, durationMin){ if(!Array.isArray(rates)||!rates.length) return {error:'请提供参会者时薪'};
  durationMin=+durationMin; if(!(durationMin>0)) return {error:'会议时长须为正'};
  var sum=0; for(var i=0;i<rates.length;i++) sum+= +rates[i];
  var cost=sum*(durationMin/60);
  return {participants:rates.length, hourlySum:sum, durationMin:durationMin, cost:Math.round(cost*100)/100}; }
function withPrep(rates, durationMin, prepMin){ prepMin=+prepMin||0; var base=meetingCost(rates,durationMin); if(base.error) return base;
  var p=meetingCost(rates,prepMin); if(p.error) return p;
  return {participants:rates.length, cost:Math.round((base.cost+p.cost)*100)/100, meeting:base.cost, prep:p.cost}; }
function annual(cost, perYear){ perYear=+perYear||1; return Math.round(cost*perYear*100)/100; }
var EXPORTS={meetingCost:meetingCost, withPrep:withPrep, annual:annual};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.MeetingCostForgePure = EXPORTS; }
